SELECT 
FROM mt_promotion_ad_realtime_snapshot
WHERE shop_id = #{shopId}
  AND biz_date = #{bizDate}
  AND slot_time = #{slotTime}
LIMIT 1

SELECT 
FROM mt_promotion_ad_realtime_snapshot
WHERE shop_id = #{shopId}
  AND slot_time >= #{startSlotTime}
  AND slot_time < #{endSlotTime}
ORDER BY slot_time DESC
LIMIT 1

SELECT 
FROM mt_promotion_ad_realtime_snapshot
WHERE shop_id = #{shopId}
  AND slot_time < #{slotTime}
ORDER BY slot_time DESC
LIMIT 1

SELECT 
FROM mt_promotion_ad_realtime_snapshot
WHERE shop_id = #{shopId}
  AND slot_time <= #{slotTime}
ORDER BY slot_time DESC
LIMIT 1

SELECT 
FROM mt_promotion_ad_realtime_snapshot
WHERE shop_id = #{shopId}
  AND slot_time >= #{startSlotTime}
  AND slot_time <= #{endSlotTime}
ORDER BY slot_time DESC
LIMIT 1

SELECT 
FROM mt_promotion_ad_realtime_snapshot
WHERE shop_id = #{shopId}
  AND slot_time >= #{startSlotTime}
  AND slot_time < #{endSlotTime}
ORDER BY slot_time ASC
LIMIT 1
